# Quiet Steps milestone tune: original, generated by this script.
# No samples and no third-party audio, so it carries no outside licence.
# About 7.2 s: soft bell/marimba-like D-major pentatonic phrase, small room,
# long fade. Played once when the milestone pop-up opens. Never looped.
#
#   python tool/make_chime.py           (needs numpy; ffmpeg for the .ogg)
#
# Writes build/milestone_chime.wav and assets/sounds/milestone_chime.ogg.
import os, shutil, subprocess, wave
import numpy as np
sr = 44100; dur = 7.2
t = np.arange(int(sr * dur)) / sr
out = np.zeros_like(t)
def note(freq, start, length, amp):
    n = int(sr * length); s = int(sr * start)
    tt = np.arange(n) / sr
    env = (1 - np.exp(-tt / 0.012)) * np.exp(-tt / (length * 0.32))
    tone = (np.sin(2*np.pi*freq*tt) + 0.18*np.sin(2*np.pi*2*freq*tt)*np.exp(-tt/0.5)
            + 0.06*np.sin(2*np.pi*2.76*freq*tt)*np.exp(-tt/0.15))
    seg = amp * env * tone
    e = min(len(out), s + n); out[s:e] += seg[:e - s]
f = lambda m: 440 * 2 ** ((m - 69) / 12)
D5, Fs5, A5, B5, D6, A4 = f(74), f(78), f(81), f(83), f(86), f(69)
for fr, st, ln, a in [(D5,0.00,2.6,.50),(Fs5,0.42,2.6,.45),(A5,0.84,2.8,.42),(B5,1.30,2.4,.30),
                      (A5,1.72,3.4,.40),(D6,2.40,4.6,.32),(A4,2.40,4.6,.22),(D5,2.40,4.6,.25)]:
    note(fr, st, ln, a)
# small Schroeder-style room
def comb(x, d, g):
    y = np.copy(x); D = int(sr*d)
    for i in range(D, len(x)): y[i] += g * y[i-D]
    return y
wet = sum(comb(out, d, g) for d, g in [(0.0297,.72),(0.0371,.70),(0.0411,.68),(0.0437,.66)]) / 4
mix = 0.78*out + 0.30*wet
fade = np.ones_like(mix); fs = int(sr*5.4); fade[fs:] = np.cos(np.linspace(0, np.pi/2, len(mix)-fs))**2
mix *= fade
mix = mix / np.max(np.abs(mix)) * 10**(-6/20)   # peak -6 dBFS
st = np.stack([mix, np.roll(mix, int(sr*0.0006))], 1)  # tiny width
pcm = (st * 32767).astype('<i2')
root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
wav = os.path.join(root, 'build', 'milestone_chime.wav')
ogg = os.path.join(root, 'assets', 'sounds', 'milestone_chime.ogg')
os.makedirs(os.path.dirname(wav), exist_ok=True)
os.makedirs(os.path.dirname(ogg), exist_ok=True)
with wave.open(wav, 'wb') as w:
    w.setnchannels(2); w.setsampwidth(2); w.setframerate(sr); w.writeframes(pcm.tobytes())
print('wrote', wav, f'{dur} s')
if shutil.which('ffmpeg'):
    subprocess.run(['ffmpeg', '-y', '-loglevel', 'error', '-i', wav,
                    '-c:a', 'libvorbis', '-q:a', '4', '-map_metadata', '-1', ogg], check=True)
    print('wrote', ogg)
else:
    print('ffmpeg not found: convert the .wav to .ogg (Vorbis) yourself')
